import test from "node:test";
import assert from "node:assert/strict";
import {apply, planner} from "./replay.mjs";

const catalog = {default:5, studios:new Map([["orchid",8], ["iris",3], ["lily",11]])};
const book = (id, units, rest = {}) => ({service:"studio", action:"book", id,
  tenant:"orchid", day:"2025-04-02", units, ...rest});
const renew = (previous, id, rest = {}) => ({service:"studio", action:"renew",
  previous, id, day:"2025-05-02", ...rest});

test("Studio allocations are tenant-specific and Archive keeps its default", () => {
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(book("orchid", 8)), {status:"booked", id:"orchid", remaining:0});
  assert.equal(dispatch(book("over", 1)).status, "full");
  assert.equal(dispatch(book("tomorrow", 8, {day:"2025-04-03"})).status, "booked");
  assert.equal(dispatch(book("small", 4, {tenant:"iris"})).status, "full");
  assert.equal(dispatch(book("large", 11, {tenant:"lily"})).status, "booked");
  assert.equal(dispatch(book("unknown", 6, {tenant:"rose"})).status, "full");
  assert.equal(dispatch(book("fallback", 5, {tenant:"rose"})).status, "booked");
  assert.equal(dispatch(book("archive", 6, {service:"archive"})).status, "full");
  assert.equal(dispatch(book("archive", 5, {service:"archive"})).status, "booked");
  assert.equal(dispatch(renew("archive", "archive-next", {service:"archive", units:6})).status, "full");
});

test("Studio preserves replay, conflicts, cancellations and tenant/day accounting", () => {
  const dispatch = planner(catalog);
  const first = book("first", 7);
  assert.equal(dispatch(first).status, "booked");
  assert.equal(dispatch(first).status, "replay");
  assert.equal(dispatch({...first, units:8}).status, "conflict");
  assert.equal(dispatch({...first, tenant:"rose"}).status, "conflict");
  assert.deepEqual(dispatch(book("too-much", 2)), {status:"full", id:"too-much", remaining:1});
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "cancelled");
  assert.equal(dispatch(first).status, "cancelled");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "replay");
  assert.equal(dispatch(book("too-much", 8)).status, "booked");
  assert.deepEqual(dispatch({service:"studio", action:"usage", tenant:"orchid", day:first.day}), {units:8});
  const summary = dispatch({service:"studio", action:"summary"});
  assert.equal(summary.occupied.length, 1);
  assert.deepEqual(summary.events.map(e => e.type), ["booked", "cancelled", "booked"]);
  assert.deepEqual(apply(dispatch, book("bad", 0)), {status:"invalid", field:"units"});
});

test("monthly renewals use the source tenant and the same admission and replay rules", () => {
  const dispatch = planner(catalog);
  dispatch(book("source", 7));
  const next = renew("source", "next", {tenant:"rose"});
  assert.deepEqual(dispatch(next), {status:"booked", id:"next", remaining:1});
  assert.equal(dispatch(next).status, "replay");
  assert.equal(dispatch({...next, units:8}).status, "conflict");
  assert.equal(dispatch(renew("source", "overflow", {units:2})).status, "full");
  assert.equal(dispatch(renew("source", "last", {units:1})).status, "booked");
  dispatch({service:"studio", action:"cancel", id:"next"});
  assert.equal(dispatch(next).status, "cancelled");
  assert.equal(dispatch(renew("source", "replacement")).status, "booked");
  dispatch(book("fallback", 5, {tenant:"rose"}));
  assert.equal(dispatch(renew("fallback", "fallback-next", {units:6})).status, "full");
  assert.equal(dispatch(renew("fallback", "fallback-next")).status, "booked");
  assert.equal(dispatch(renew("absent", "missing")).status, "missing");
  dispatch({service:"studio", action:"cancel", id:"source"});
  assert.equal(dispatch(renew("source", "cancelled-source")).status, "missing");
});

test("imports bypass admission but still count, and existing IDs replay even above quota", () => {
  const dispatch = planner(catalog);
  const imported = book("backfill", 12);
  assert.equal(dispatch({...imported, action:"import"}).status, "imported");
  assert.equal(dispatch(imported).status, "replay");
  assert.equal(dispatch(renew("backfill", "next")).status, "full");
  assert.deepEqual(dispatch(book("extra", 1)), {status:"full", id:"extra", remaining:0});
  dispatch({service:"studio", action:"cancel", id:"backfill"});
  assert.equal(dispatch(book("extra", 8)).status, "booked");
});
EOF
