import test from "node:test";
import assert from "node:assert/strict";
import {mkdtempSync, readFileSync, writeFileSync, rmSync} from "node:fs";
import {tmpdir} from "node:os";
import {join} from "node:path";
import {fileURLToPath} from "node:url";
import {spawnSync} from "node:child_process";
import {projectCalendar, publicationRecords} from "./utilization.mjs";
import {readCatalog} from "./common/limits.mjs";

const command = fileURLToPath(new URL("./utilization.mjs", import.meta.url));
const pilot = JSON.parse(readFileSync(new URL("./fixtures/pilot.json", import.meta.url)));
const cell = (service, tenant, day, used = 2) => ({service, tenant, day,
  edition:"old", cap:5, used, available:5-used});
const book = (id, tenant, day, units, action = "book") =>
  ({service:"studio", action, id, tenant, day, units});

function files(t, source, rows) {
  const dir = mkdtempSync(join(tmpdir(), "studio-calendar-"));
  t.after(() => rmSync(dir, {recursive:true, force:true}));
  const feed = join(dir, "feed.json");
  const diary = join(dir, "diary.json");
  writeFileSync(feed, JSON.stringify(source));
  writeFileSync(diary, JSON.stringify(rows));
  return {feed, diary, run:(operation = "publish-calendar") =>
    spawnSync(process.execPath, [command, operation, feed, diary], {encoding:"utf8"})};
}

test("pilot publishes only its audience and inclusive dates; reapplication is byte-identical", t => {
  const untouched = [cell("archive", "orchid", "2025-04-02"),
    cell("studio", "iris", "2025-04-02"), cell("studio", "orchid", "2025-04-01"),
    cell("studio", "orchid", "2025-04-04")];
  const {diary, run} = files(t, pilot, [...untouched, cell("studio", "orchid", "2025-04-02")]);
  const result = run();
  assert.equal(result.status, 0, result.stderr);
  assert.deepEqual(JSON.parse(result.stdout), {edition:"orchid-quota", rows:2});
  const rows = JSON.parse(readFileSync(diary, "utf8"));
  assert.deepEqual(rows.slice(0, 4), untouched);
  assert.deepEqual(rows.slice(4), [
    {service:"studio", tenant:"orchid", day:"2025-04-02", edition:"orchid-quota", cap:8, used:7, available:1},
    {service:"studio", tenant:"orchid", day:"2025-04-03", edition:"orchid-quota", cap:8, used:0, available:8}
  ]);
  const before = readFileSync(diary, "utf8");
  assert.equal(run().status, 0);
  assert.equal(readFileSync(diary, "utf8"), before);
});

test("publication replays operations outside the window before selecting cells", t => {
  const source = {...pilot, operations:[
    book("source", "orchid", "2025-04-01", 7),
    {service:"studio", action:"renew", previous:"source", id:"renewed", day:"2025-04-02"},
    book("cancelled", "orchid", "2025-04-03", 6),
    {service:"studio", action:"cancel", id:"cancelled"},
    book("claimed", "iris", "2025-04-04", 1),
    book("claimed", "orchid", "2025-04-03", 2),
    book("backfill", "orchid", "2025-04-03", 10, "import")
  ]};
  const {diary, run} = files(t, source, []);
  const result = run();
  assert.equal(result.status, 0, result.stderr);
  assert.deepEqual(JSON.parse(readFileSync(diary, "utf8")).map(r => [r.day, r.used, r.available]),
    [["2025-04-02",7,1], ["2025-04-03",10,0]]);
});

test("full projections, previews and rebuilds remain unscoped", t => {
  const source = {...pilot};
  delete source.window;
  const {diary, run} = files(t, source, []);
  const preview = run("preview-calendar");
  assert.equal(preview.status, 0, preview.stderr);
  assert.equal(JSON.parse(preview.stdout).length, 12);
  assert.equal(readFileSync(diary, "utf8"), "[]");
  assert.equal(run("rebuild-calendar").status, 0);
  assert.equal(JSON.parse(readFileSync(diary, "utf8")).length, 12);
});

test("invalid publication windows fail without writing the diary", t => {
  for (const window of [undefined, {}, {...pilot.window, service:"other"},
    {...pilot.window, tenant:"Bad"}, {...pilot.window, from:"2025-02-30"},
    {...pilot.window, through:"2025-04-01"}]) {
    const {diary, run} = files(t, {...pilot, window}, []);
    assert.notEqual(run().status, 0);
    assert.equal(readFileSync(diary, "utf8"), "[]");
  }
});

test("window selection supports Archive, fallback tenants, and a single inclusive day", () => {
  const projected = projectCalendar(pilot, readCatalog());
  const rows = publicationRecords(projected,
    {service:"archive", tenant:"orchid", from:"2025-04-02", through:"2025-04-02"});
  assert.equal(rows.length, 1);
  assert.equal(rows[0].cap, 5);
